package org.apache.commons.jxpath.ri;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import org.apache.commons.jxpath.NodePointer;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.NamespaceContextPointer;
import org.apache.commons.jxpath.ri.NamespaceResolver;
import org.apache.commons.jxpath.ri.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

public class NamespaceResolver_getPrefix_TriageGen2Test {

    /**
     * Test case for when reverseMap is null and ni is null.
     * Covers: reverseMap == null, ni == null, and the fallback to parent.
     */
    @Test
    public void testGetPrefix_NullNiAndNoParent() {
        NamespaceResolver resolver = new NamespaceResolver();
        // Force reverseMap to null by not calling anything that initializes it
        // and ensure pointer returns null iterator
        Pointer mockPointer = mock(Pointer.class);
        when(mockPointer.namespaceIterator()).thenReturn(null);

        // We need to use reflection or a subclass if we can't set pointer directly via public API 
        // but based on the provided signature, we use setNamespaceContextPointer
        resolver.setNamespaceContextPointer(new NamespaceContextPointer(mockPointer));

        assertNull(resolver.getPrefix("http://example.com"));
    }

    /**
     * Test case for when reverseMap is null, ni is not null, and contains valid prefixes.
     * Covers: reverseMap == null, ni != null loop, and namespaceMap entries.
     */
    @Test
    public void testGetPrefix_WithNiAndNamespaceMap() {
        NamespaceResolver resolver = new NamespaceResolver();

        // Mocking NodeIterator and NodePointer for the loop
        NodeIterator mockNi = mock(NodeIterator.class);
        NodePointer mockNodePointer = mock(NodePointer.class);

        when(mockNi.setPosition(1)).thenReturn(true);
        when(mockNi.setPosition(2)).thenReturn(false);
        when(mockNi.getNodePointer()).thenReturn(mockNodePointer);

        // Setup URI and Prefix
        when(mockNodePointer.getNamespaceURI()).thenReturn("http://ni.com");
        // Mocking Name object for nsPointer.getName().getName()
        org.apache.commons.jxpath.Name mockName = mock(org.apache.commons.jxpath.Name.class);
        when(mockNodePointer.getName()).thenReturn(mockName);
        when(mockName.getName()).thenReturn("ni_prefix");

        Pointer mockPointer = mock(Pointer.class);
        when(mockPointer.namespaceIterator()).thenReturn(mockNi);
        resolver.setNamespaceContextPointer(new NamespaceContextPointer(mockPointer));

        // Register a namespace via the official method to populate namespaceMap
        resolver.registerNamespace("map_prefix", "http://map.com");

        // Execute
        assertEquals("ni_prefix", resolver.getPrefix("http://ni.com"));
        assertEquals("map_prefix", resolver.getPrefix("http://map.com"));
    }

    /**
     * Test case for empty prefix in NodeIterator.
     * Covers: if (!"".equals(prefix)) branch.
     */
    @Test
    public void testGetPrefix_EmptyPrefixInNi() {
        NamespaceResolver resolver = new NamespaceResolver();
        NodeIterator mockNi = mock(NodeIterator.class);
        NodePointer mockNodePointer = mock(NodePointer.class);
        org.apache.commons.jxpath.Name mockName = mock(org.apache.commons.jxpath.Name.class);

        when(mockNi.setPosition(1)).thenReturn(true);
        when(mockNi.setPosition(2)).thenReturn(false);
        when(mockNi.getNodePointer()).thenReturn(mockNodePointer);
        when(mockNodePointer.getNamespaceURI()).thenReturn("http://empty.com");
        when(mockNodePointer.getName()).thenReturn(mockName);
        when(mockName.getName()).thenReturn(""); // Empty prefix

        Pointer mockPointer = mock(Pointer.class);
        when(mockPointer.namespaceIterator()).thenReturn(mockNi);
        resolver.setNamespaceContextPointer(new NamespaceContextPointer(mockPointer));

        assertNull(resolver.getPrefix("http://empty.com"));
    }

    /**
     * Test case for parent delegation.
     * Covers: prefix == null && parent != null.
     */
    @Test
    public void testGetPrefix_ParentDelegation() {
        // Create parent
        NamespaceResolver parent = new NamespaceResolver();
        parent.registerNamespace("parent_prefix", "http://parent.com");

        // Create child
        NamespaceResolver child = new NamespaceResolver(parent);

        // Ensure child's reverseMap is initialized but doesn't have the URI
        Pointer mockPointer = mock(Pointer.class);
        when(mockPointer.namespaceIterator()).thenReturn(null);
        child.setNamespaceContextPointer(new NamespaceContextPointer(mockPointer));

        // The child should delegate to parent
        assertEquals("parent_prefix", child.getPrefix("http://parent.com"));
    }

    /**
     * Test case for when reverseMap is already initialized.
     * Covers: if (reverseMap == null) being false.
     */
    @Test
    public void testGetPrefix_AlreadyInitialized() {
        NamespaceResolver resolver = new NamespaceResolver();
        resolver.registerNamespace("p", "http://p.com");

        // First call initializes it
        resolver.getPrefix("http://p.com");

        // Second call should use existing map
        assertEquals("p", resolver.getPrefix("http://p.com"));
    }
}
